import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uniform, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

function roundedRectShape(THREE, w, h, r) {
  const shape = new THREE.Shape();
  const x = -w / 2;
  const y = -h / 2;
  shape.moveTo(x, y + r);
  shape.lineTo(x, y + h - r);
  shape.quadraticCurveTo(x, y + h, x + r, y + h);
  shape.lineTo(x + w - r, y + h);
  shape.quadraticCurveTo(x + w, y + h, x + w, y + h - r);
  shape.lineTo(x + w, y + r);
  shape.quadraticCurveTo(x + w, y, x + w - r, y);
  shape.lineTo(x + r, y);
  shape.quadraticCurveTo(x, y, x, y + r);
  return shape;
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, ExtrudeGeometry, PlaneGeometry, CircleGeometry, Color, Vector3, DirectionalLight } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = items.find((i) => i.role === 'headline') ?? items[0] ?? { text: 'Journal 2' };

  const group = new Group();
  group.position.set(0, 1, 0.06);

  const disposables = [];
  const primitiveHandles = [];
  const gsapTimelines = [];

  // ---- Backing plaque (machined metal, bevel via extrude) ----
  const plateW = 1.6;
  const plateH = 0.56;
  const plateShape = roundedRectShape(THREE, plateW, plateH, 0.06);
  const plateGeo = new ExtrudeGeometry(plateShape, {
    depth: 0.08,
    bevelEnabled: true,
    bevelThickness: 0.02,
    bevelSize: 0.02,
    bevelSegments: 3,
    curveSegments: 8,
  });
  disposables.push(plateGeo);

  const plateMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.45,
    roughness: 0.52,
    clearcoat: 0.18,
    clearcoatRoughness: 0.35,
  });
  disposables.push(plateMat);

  const plate = new Mesh(plateGeo, plateMat);
  plate.position.z = -0.04;
  group.add(plate);

  // ---- Thumbnail chip: textured with provided image, anodized-look ----
  const chipW = 0.42;
  const chipH = 0.42;
  const chipGeo = new PlaneGeometry(chipW, chipH);
  disposables.push(chipGeo);
  const chipMat = new MeshBasicNodeMaterial({ color: new Color(colors.surface), transparent: true, opacity: 0.9 });
  disposables.push(chipMat);
  const chip = new Mesh(chipGeo, chipMat);
  chip.position.set(-plateW / 2 + chipW / 2 + 0.12, 0, 0.045);
  group.add(chip);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      chipMat.map = tex;
      chipMat.color.set('#ffffff');
      chipMat.opacity = 1.0;
      chipMat.needsUpdate = true;
    });
  }

  // ---- Accent edge stripe (focus indicator, signal red) ----
  const stripeGeo = new PlaneGeometry(plateW * 0.86, 0.02);
  disposables.push(stripeGeo);
  const accentIntensity = uniform(0.6);
  const stripeMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    roughness: 0.4,
    metalness: 0.1,
  });
  stripeMat.emissiveNode = vec3(
    colors.accent ? new Color(colors.accent).r : 1,
    colors.accent ? new Color(colors.accent).g : 0,
    colors.accent ? new Color(colors.accent).b : 0.2
  ).mul(accentIntensity);
  disposables.push(stripeMat);
  const stripe = new Mesh(stripeGeo, stripeMat);
  stripe.position.set(0, -plateH / 2 + 0.05, 0.05);
  group.add(stripe);

  // ---- Headline text ----
  const textObj = ctx.fontAtlas.createText(headline.text ?? 'Journal 2', {
    fontSize: headline.typography?.fontSize ?? 39,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 420,
  });
  textObj.position.set(-plateW / 2 + chipW + 0.22, -0.03, 0.05);
  group.add(textObj);

  // ---- Local rim/accent light (opposite key, carries accent hue) ----
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.7);
  rimLight.position.set(-1.2, -0.6, 1.4);
  group.add(rimLight);
  disposables.push(rimLight);

  // ---- Contact shadow (grounding) ----
  const shadowGeo = new CircleGeometry(0.85, 32);
  disposables.push(shadowGeo);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color('#000000'),
    transparent: true,
    opacity: 0.45,
  });
  disposables.push(shadowMat);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -plateH / 2 - 0.02, -0.02);
  group.add(shadow);

  // ---- Cinematic primitive: parallax-scroll ----
  const parallaxSpec = (config.cinematicPrimitives ?? []).find((p) => p.name === 'parallax-scroll');
  if (parallaxSpec) {
    const handle = ctx.primitives['parallax-scroll'](group, parallaxSpec.params ?? { intensity: 0.25 });
    primitiveHandles.push(handle);
  }

  // ---- Idle weighted breathing (single slow transform) ----
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(plate.scale, { x: 1.015, y: 1.015, z: 1.015, duration: 4.5, ease: 'sine.inOut' });
  gsapTimelines.push(idleTl);

  // ---- Interaction: hover -> rise-in (subtle lift) ----
  const baseY = group.position.y;
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(group.position, { y: baseY + 0.15, duration: 0.35, ease: 'power3.out' }, 0);
  hoverTl.to(accentIntensity, { value: 1.8, duration: 0.3, ease: 'power2.out' }, 0);
  hoverTl.to(plate.rotation, { x: -0.03, duration: 0.3, ease: 'power2.out' }, 0);
  gsapTimelines.push(hoverTl);

  function onHoverStart() {
    hoverTl.play();
  }
  function onHoverEnd() {
    hoverTl.reverse();
  }

  // ---- Interaction: click -> press-down + emit navigation event ----
  function onClick() {
    const pressTl = gsap.timeline();
    pressTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    pressTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.35, ease: 'power4.out' });
    gsapTimelines.push(pressTl);
    ctx.emit('hub-journal.select', { id: 'hub-journal-card-0', node: config.id ?? 'hub-journal-card-0-label' });
    ctx.emit('navigate', { to: 'hub-journal' });
  }

  group.userData.handlers = {
    onPointerOver: onHoverStart,
    onPointerOut: onHoverEnd,
    onClick,
  };

  group.userData.cleanup = () => {
    for (const tl of gsapTimelines) {
      tl.kill();
    }
    for (const handle of primitiveHandles) {
      handle?.cleanup?.();
    }
    for (const res of disposables) {
      res?.dispose?.();
    }
    if (chipMat.map) {
      chipMat.map.dispose?.();
    }
    if (textObj?.userData?.cleanup) {
      textObj.userData.cleanup();
    }
  };

  return group;
}
